#define PI 3.1415926538

float rtPlane(in vec3 ro, in vec3 rd, in vec4 pla)
{
    return -(pla.w + dot(pla.xyz, ro))/dot(pla.xyz, rd);
}

bool pointInTriangle(in vec3 p, in mat3 def, inout float alpha, inout float beta)
{
    vec3 U = p - def[0];
    vec3 V = def[1] - def[0];
    vec3 W = def[2] - def[0];

    float dVW = dot(V, W);
    mat2 A = mat2(vec2(dot(V, V), dVW), vec2(dVW, dot(W, W)));

    float dUV = dot(U, V);
    float dUW = dot(U, W);

    float d = determinant(A);

    if (abs(d)<1e-5)
        return false;

    vec2 res = inverse(A) * vec2(dUV, dUW);

    alpha = res[0];
    beta = res[1];

    return (res[0] >= 0.0 && res[1] >= 0.0 && (res[0] + res[1] <= 1.0));
}

vec4 getPlane(in mat3 def)
{
    vec3 A = def[0];
    vec3 B = def[1];
    vec3 C = def[2];

    vec3 AB = normalize(def[1] - def[0]);
    vec3 AC = normalize(def[2] - def[0]);
    vec3 K  = normalize(cross(AB, AC));

    return vec4(K, -dot(K, A));
}

mat3 mX(in float t)
{
    float ct = cos(t);
    float st = sin(t);
    return mat3(
        1.0, 0.0, 0.0,
        0.0, ct, -st,
        0.0, st, ct
    );
}

mat3 mY(in float t)
{
    float ct = cos(t);
    float st = sin(t);
    return mat3(ct, 0.0, -st, 0.0, 1.0, 0.0, st, 0.0, ct);
}

mat3 mZ(in float t)
{
    float ct = cos(t);
    float st = sin(t);
    return mat3(
        ct, -st, 0.0,
        st,  ct, 0.0,
        0.0, 0.0, 1.0
    );
}

float rtSphere(in vec3 ro, in vec3 rd, in vec3 sc, in float r)
{
    vec3 oc = ro - sc;
    float b = dot(rd, oc);
    float c = dot(oc, oc) - r*r;
    float t = b*b - c;

    if (0.0 > t)
        return -1.0;

    float g = sqrt(t);
    return min((-b + g), (-b - g));
}

mat3 getCameraUVW(in vec3 w)
{
    vec3 u = normalize(cross(w,vec3(0,1,0)));
    vec3 v = normalize(cross(u, w));
    return mat3(u,v,-w);
}

float checkerboard(vec3 p, float scale)
{
    vec2 coord = p.xz * scale;

    ivec2 i = ivec2(floor(coord));

    if ((i.x + i.y) % 2 == 0)
    {
        return 1.0;
    }
    else
    {
        return 0.0;
    }
}

vec2 hash22( vec2 p ) 
{
	p = vec2( dot(p,vec2(127.1,311.7)), dot(p,vec2(269.5,183.3)) );
	return -1.0 + 2.0*fract(sin(p)*43758.5453123);
}

void renderVertices(in vec3 ro, in vec3 rd, in mat3 tri, inout vec3 col)
{
    return;

    const float radius = .025;
    float t0 = rtSphere(ro, rd, tri[0], radius);
    float t1 = rtSphere(ro, rd, tri[1], radius);
    float t2 = rtSphere(ro, rd, tri[2], radius);

    if (!(0.0 > t0))
        col = mix(col,vec3(0),.95);
    if (!(0.0 > t1))
        col = mix(col,vec3(0),.95);
    if (!(0.0 > t2))
        col = mix(col, vec3(0), .95);
}

vec3 Centroid(in mat3 tri)
{
    return (tri[0] + tri[1] + tri[2]) / 3.0;
}

mat3 rotateAboutCentroid(in mat3 rot, in mat3 tri)
{
    mat3 ctri = tri;
    vec3 c = Centroid(ctri);
    ctri[0] -= c;
    ctri[1] -= c;
    ctri[2] -= c;

    ctri = rot * ctri;
    ctri[0] += c;
    ctri[1] += c;
    ctri[2] += c;

    return ctri;
}

bool getPerpendicularAndPoint(in vec4 pla1, in vec4 pla2, out vec3 perp, out vec3 point)
{
    perp = normalize(cross(pla1.xyz, pla2.xyz));
    mat3 mat = transpose(mat3(pla1.xyz, pla2.xyz, perp));
    float det = determinant(mat);
    vec3 knowns = vec3(pla1.w, pla2.w, 1.0);

    if (abs(det) < 1e-5)
        return false;

    point = vec3(
        (1.0 / det) * determinant(transpose(mat3(  knowns, pla2.xyz,   perp))),
        (1.0 / det) * determinant(transpose(mat3(pla1.xyz,   knowns,   perp))),
        (1.0 / det) * determinant(transpose(mat3(pla1.xyz, pla2.xyz, knowns)))
    );

    return true;
}


void mainImage( out vec4 O, in vec2 F )
{
    vec2 R = iResolution.xy,
        uv = (2.0*F - R)/R.y;

    float focal_length = 2.0;
    vec3 ro = mY(iTime*.65)* vec3(0, smoothstep(0.6, 1.0,0.8 + 0.1 * cos(iTime*1.5)),focal_length);
    vec3 focus_point = vec3(0);
    vec3 look_at_dir = normalize(focus_point - ro);
    mat3 cam = getCameraUVW(look_at_dir);

    vec3 rd = normalize(cam * vec3(uv, -1));

    vec3 col = (1.0-exp(-7.25*abs(uv.y)))*vec3(1,1,.99);//vec3(.5,.8,1.1);

    vec3 groundPoint;
    float t0 = rtPlane(ro, rd, vec4(0,1,0,0));
    if (!(0.0 > t0))
    {
        groundPoint = ro + t0*rd;
        if (abs(groundPoint.x)<2.0 && abs(groundPoint.z)<2.0)
            col = mix(col,checkerboard(groundPoint,2.0)<.5?vec3(1):vec3(.97),
            smoothstep(1.9,0.5,abs(groundPoint.z))*smoothstep(1.9,0.5, abs(groundPoint.x)));
    }

    float rot = iTime*0.5;
    mat3 tri1 = rotateAboutCentroid(mX( rot)*mY(-rot+hash22(vec2(0,1)).x), 1.2*mat3(vec3( -1,  .0, .1), vec3( 1, -.5,.1), vec3(0,1.,-.1)));
    mat3 tri2 = rotateAboutCentroid(mY( rot)*mZ( rot+hash22(vec2(1,2)).x), 1.2*mat3(vec3( 0, -.2, .25), vec3( .1, -.1, -.35), vec3(-.2, 1.2, -.1)));
    mat3 tri3 = rotateAboutCentroid(mZ(-rot)*mX( rot-hash22(vec2(3,4)).x), 1.2*mat3(vec3( -.3, .9, .4), vec3(-.2, .7, -.5), vec3(.3, -.3, 0)));

    vec4 pla1 = getPlane(tri1);
    vec4 pla2 = getPlane(tri2);
    vec4 pla3 = getPlane(tri3);

   // renderVertices(ro,rd,tri1,col);
   // renderVertices(ro,rd,tri2,col);
  //  renderVertices(ro,rd,tri3,col);

    float t1 = rtPlane(ro, rd, pla1);
    float t2 = rtPlane(ro, rd, pla2);
    float t3 = rtPlane(ro, rd, pla3);

    vec3 p1 = vec3(0,0,100000);
    vec3 p2 = vec3(0,0,100000);
    vec3 p3 = vec3(0,0,100000);

    if (!(0.0 > t1))
        p1 = ro + t1*rd;
    if (!(0.0 > t2))
        p2 = ro + t2*rd;
    if (!(0.0 > t3))
        p3 = ro + t3*rd;

    float a1, b1;
    float a2, b2;
    float a3, b3;

    bool inT1 = pointInTriangle(p1,tri1,a1,b1);
    bool inT2 = pointInTriangle(p2,tri2,a2,b2);
    bool inT3 = pointInTriangle(p3,tri3,a3,b3);
    bool inAll = inT1&&inT2&&inT3;

    vec3 col1 = vec3(a1, b1,  1);
    vec3 col2 = vec3( 1, a2, b2);
    vec3 col3 = vec3(a3,  0, b3);

    vec2 st1 = vec2(a1,b1) * 10.0;
    vec2 st2 = vec2(a2,b2) * 10.0;
    vec2 st3 = vec2(a3,b3) * 10.0;

    if (inT1 && inT2)
        col = col1+col2;
    else if (inT1 && inT3)
        col = col1+col3;
    else if (inT2 && inT3)
        col = col2+col3;
    else if (inT1)
        col = vec3(a1,b1,1);
    else if (inT2)
        col = vec3(1,vec2(a2,b2));
    else if (inT3)
        col = vec3(b3*1.5,a3,.5);

#if 0  
    bool on_line = false;
    if (inT1)
    {
        vec3 perp;
        vec3 point;
        if (getPerpendicularAndPoint(pla1, pla2, perp, point))
        {
            vec3 n = normalize(p1 - point);
            if (abs(abs(dot(n,perp))-1.0) < 1e-3)
            {
                on_line = true;
                col = vec3(0);
            }
        }
    }

    if (on_line)
    {
        O = vec4(col,1);
        return;
    }
#endif     

    float v1x = abs(fract(st1.x));
    float v2y = abs(fract(st2.y));
    float v3x = abs(fract(st3.x));
    col = inT1?mix(col,col*0.95,smoothstep(-1.0, 1.0, (v1x - 0.9)/fwidth(v1x))):col;
    col = inT2?mix(col,col*0.95,smoothstep(-1.0, 1.0, (v2y - 0.9)/fwidth(v2y))):col;
    col = inT3?mix(col,col*0.95,smoothstep(-1.0, 1.0, (v3x - 0.9)/fwidth(v3x))):col;

    float det = determinant(transpose(mat3(pla1.xyz, pla2.xyz, pla3.xyz)));

    if (abs(det) > 1e-5)
    {
        vec3 B = vec3(pla1.w, pla2.w, pla3.w);
        float x = (-1.0 / det) * determinant(transpose(mat3(       B, pla2.xyz, pla3.xyz)));
        float y = (-1.0 / det) * determinant(transpose(mat3(pla1.xyz,        B, pla3.xyz)));
        float z = (-1.0 / det) * determinant(transpose(mat3(pla1.xyz, pla2.xyz,        B)));

        vec3 centre = vec3(x, y, z);

        float m = rtSphere(ro, rd, centre, inAll?.25:.125);
        if (!(0.0 > m))
        {
            vec3 p = ro + m*rd;
            vec3 n = normalize(p-centre);
            vec3 c = normalize(ro - p);
            float f = 1.5*(1.1-abs(dot(n,c)));

            col = (inAll?(1.0/distance(p,centre))*vec3(.5):abs(n.xyz))*f;
        }
    }


    O = vec4(col,1.0);
}
